<div class="page-heading"><div><span class="eyebrow">Mejora continua</span><h1>Ciclo PHVA</h1><p>Planear, Hacer, Verificar y Actuar con responsables, evidencias y seguimiento.</p></div><a href="<?= e(url('/plan-anual')) ?>" class="btn-primary"><?= icon('calendar', 'h-4 w-4') ?> Abrir Plan Anual</a></div>
<section class="mt-7 grid gap-4 md:grid-cols-2 xl:grid-cols-4"><?php $phaseData = ['Planear' => ['Definir rumbo y recursos', 'clipboard', 'P'], 'Hacer' => ['Implementar y controlar', 'settings', 'H'], 'Verificar' => ['Medir y contrastar', 'search', 'V'], 'Actuar' => ['Mejorar con evidencia', 'phva', 'A']]; foreach ($phaseData as $phase => $meta): $items = $phases[$phase]; $approved = count(array_filter($items, fn($item) => $item['estado'] === 'Aprobado')); $percent = count($items) ? round($approved / count($items) * 100) : 0; ?><article class="ios-card p-5"><div class="flex items-start justify-between"><span class="phase-icon phase-<?= strtolower($phase) ?>"><?= icon($meta[1], 'h-5 w-5') ?></span><span class="text-2xl font-semibold tracking-tight text-slate-300"><?= $meta[2] ?></span></div><h2 class="mt-5 text-lg font-semibold"><?= $phase ?></h2><p class="mt-1 text-xs text-slate-400"><?= e($meta[0]) ?></p><div class="mt-5 flex justify-between text-[11px]"><span class="text-slate-500"><?= $approved ?>/<?= count($items) ?> aprobados</span><strong><?= $percent ?>%</strong></div><div class="progress-track mt-2"><span class="bg-blue-500" style="width: <?= $percent ?>%"></span></div></article><?php endforeach; ?></section>
<div class="mt-6 grid gap-6 xl:grid-cols-[1.25fr_0.75fr]">
    <section class="ios-card overflow-hidden"><div class="card-heading"><div><h2>Documentos por fase</h2><p>Accede directamente a los puntos que requieren intervención.</p></div><a href="<?= e(url('/documentos')) ?>" class="text-link">Biblioteca <?= icon('arrow-right', 'h-3.5 w-3.5') ?></a></div><div class="divide-y divide-slate-100"><?php foreach ($phaseData as $phase => $meta): ?><details class="group"><summary class="flex cursor-pointer list-none items-center gap-3 px-5 py-4 hover:bg-slate-50"><span class="phase-icon h-9 w-9 phase-<?= strtolower($phase) ?>"><?= icon($meta[1], 'h-4 w-4') ?></span><div class="flex-1"><p class="text-sm font-semibold"><?= $phase ?></p><p class="mt-0.5 text-[11px] text-slate-400"><?= count($phases[$phase]) ?> documentos</p></div><?= icon('chevron-down', 'h-4 w-4 text-slate-400 transition group-open:rotate-180') ?></summary><div class="grid gap-2 bg-slate-50/70 p-4 sm:grid-cols-2"><?php foreach ($phases[$phase] as $document): ?><a href="<?= e(url('/documentos/' . $document['id'])) ?>" class="flex items-center gap-3 rounded-xl bg-white p-3 ring-1 ring-slate-200/60 transition hover:ring-blue-200"><span class="badge <?= status_class($document['estado']) ?> !px-1.5"><?= $document['estado'] === 'Aprobado' ? icon('check', 'h-3 w-3') : icon('clock', 'h-3 w-3') ?></span><span class="min-w-0 flex-1 truncate text-[11px] font-medium text-slate-600"><?= e($document['nombre_documento']) ?></span><?= icon('chevron-right', 'h-3.5 w-3.5 text-slate-300') ?></a><?php endforeach; ?></div></details><?php endforeach; ?></div></section>
    <div class="space-y-6"><section class="ios-card p-5"><h2 class="text-base font-semibold">Indicadores de gestión</h2><p class="mt-1 text-xs text-slate-400">Una lectura rápida del sistema</p><div class="mt-5 grid grid-cols-2 gap-3"><a href="<?= e(url('/plan-anual')) ?>" class="rounded-2xl bg-blue-50 p-4"><p class="text-2xl font-semibold text-blue-700"><?= (int) $planStats['completadas'] ?>/<?= (int) $planStats['total'] ?></p><p class="mt-1 text-[11px] text-blue-600">PAT completado</p></a><a href="<?= e(url('/matriz-ipevr')) ?>" class="rounded-2xl bg-amber-50 p-4"><p class="text-2xl font-semibold text-amber-700"><?= (int) $hazardStats['prioritarios'] ?></p><p class="mt-1 text-[11px] text-amber-600">Riesgos prioritarios</p></a><a href="<?= e(url('/hallazgos')) ?>" class="rounded-2xl bg-violet-50 p-4"><p class="text-2xl font-semibold text-violet-700"><?= count($findings) ?></p><p class="mt-1 text-[11px] text-violet-600">ACPA en seguimiento</p></a><a href="<?= e(url('/indicadores')) ?>" class="rounded-2xl bg-emerald-50 p-4"><p class="text-2xl font-semibold text-emerald-700"><?= count($indicators) ?></p><p class="mt-1 text-[11px] text-emerald-600">Mediciones recientes</p></a></div></section><section class="ios-card p-5"><div class="flex items-center justify-between"><h2 class="text-base font-semibold">Acciones próximas</h2><a href="<?= e(url('/hallazgos')) ?>" class="text-link">Ver ACPA</a></div><div class="mt-4 space-y-3"><?php if ($findings === []): ?><p class="text-xs text-slate-400">No hay hallazgos abiertos.</p><?php endif; ?><?php foreach (array_slice($findings, 0, 4) as $finding): ?><a href="<?= e(url('/hallazgos')) ?>" class="block rounded-xl bg-slate-50 p-3"><p class="text-xs font-medium leading-5 text-slate-600"><?= e(excerpt($finding['accion_correctiva'], 85)) ?></p><p class="mt-1.5 text-[10px] text-slate-400">Límite: <?= format_date($finding['fecha_limite']) ?> · <?= e($finding['responsable']) ?></p></a><?php endforeach; ?></div></section></div>
</div>
